// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0)); // owner is address(0), so any actor is a non-owner
        address ownerBefore = c.owner();
        vm.prank(actor);
        c.transferOwnership(newOwner);
        // General rule: a non-owner caller can never change the owner.
        assertTrue(c.owner() == ownerBefore);
    }
}

