pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address firstOwner, address secondOwner) public {
        // Initially owner == address(0); the legitimate transfer comes from the current owner.
        vm.prank(c.owner());
        c.transferOwnership(firstOwner);

        // A different caller must NOT be able to change ownership afterwards.
        vm.assume(caller != c.owner());
        vm.prank(caller);
        c.transferOwnership(secondOwner);

        assertTrue(c.owner() == firstOwner);
    }
}

