pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // Admissible domain: the caller must be the current owner, otherwise
        // owned() reverts in BOTH versions (onlyOwner) and the call says nothing.
        vm.assume(actor == c.owner());

        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        // General rule: a call from the owner to owned() succeeds (no revert).
        // Reference C: body is empty -> success. Mutant: always revert() -> fails here.
        assertTrue(ok);
    }
}

