pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // owner is address(0), so only the owner (address(0)) may call owned();
        // vm.prank(address(0)) lets us drive c through owned as the current owner.
        vm.prank(address(0));
        c.owned();
        // General rule: owned() must never modify the stored owner.
        assertTrue(c.owner() == address(0));
    }
}

