pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        // Drive the entry under test; in the reference it is a no-op.
        vm.prank(actor);
        c.owned();
        // Rule: owned() must never grant ownership, so a subsequent
        // transferOwnership by the same caller must revert for any caller
        // (ownership was never legitimately transferred to anyone).
        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

