import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // Admissible domain: any caller except the (initial) owner address(0).
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // General rule: a non-owner's call to owned() always reverts (no ownership is conferred).
        assertTrue(!ok);
    }
}
